<script lang="ts">
 import {enhance} from '$app/forms';import {onMount,untrack} from 'svelte';import {ArrowLeft,MapPin,Sparkles,CheckCircle2,AlertTriangle,CalendarDays} from 'lucide-svelte';
 import {jobLabel,visibleJobs,type JobsPage} from '$lib/jobs';
 let {data,form}:{data:JobsPage;form?:{message?:string;failed?:boolean;createdId?:string;bob?:{id:string;status:string;confirmationRequired:boolean;resultJson?:string};recommendations?:{membershipId:string;eligible:boolean;explanation:string}[]}|null}=$props();
 let view=$state(untrack(()=>data.fieldView?'today':'attention')),busy=$state(false),online=$state(true),ready=$state(false),fieldMode=$state(untrack(()=>data.fieldView)),start=$state(''),end=$state('');
 const selected=$derived(data.selected),job=$derived(selected?.job),execution=$derived(job?.execution),base=$derived(data.basePath.replace('/jobs',''));
 const structured=$derived.by(()=>{try{return form?.bob?.resultJson?JSON.parse(form.bob.resultJson) as {observation?:string;possibleIssues?:string[];possibleRequirements?:string[];nextAction?:string}:null;}catch{return null;}});
 const rows=$derived(visibleJobs(data.fieldView&&view!=='all'?data.workspace.jobs.filter(j=>j.assignedToMe):data.workspace.jobs,view));
 const blockers=$derived(!selected?[]:['DRAFT','PLANNING','READY_TO_SCHEDULE'].includes(selected.state)?selected.scheduleBlockers:['READY_FOR_COMPLETION','COMPLETION_REVIEW','COMPLETED'].includes(selected.state)?selected.completionBlockers:selected.startBlockers);
 const disabled=$derived(busy||!online||!ready);
 function updateUtc(event:Event,field:string){const input=event.currentTarget as HTMLInputElement;const hidden=input.form?.elements.namedItem(field) as HTMLInputElement|null;if(hidden&&input.value)hidden.value=new Date(input.value).toISOString();}
 function localDate(value:string){const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
 const submit=()=>{busy=true;return async({update}:{update:()=>Promise<void>})=>{try{await update();}finally{busy=false;}};};
 onMount(()=>{ready=true;online=navigator.onLine;const sync=()=>online=navigator.onLine;window.addEventListener('online',sync);window.addEventListener('offline',sync);if('serviceWorker'in navigator)void navigator.serviceWorker.register('/jobs-service-worker.js',{scope:data.basePath}).catch(()=>{});return()=>{window.removeEventListener('online',sync);window.removeEventListener('offline',sync);};});
</script>
<svelte:head><title>Jobs · TurnKeyOps</title><link rel="manifest" href={`${data.basePath}/manifest.webmanifest`}/></svelte:head>
<section class="jobs mx-auto max-w-5xl space-y-5 p-4 pb-16 sm:p-6" aria-label="Job workspace">
 {#if !online}<p role="status" class="notice">Offline. Changes are not synced. Keep this page open and reconnect before saving.</p>{/if}
 {#if form?.message}<p role={form.failed?'alert':'status'} class="notice">{form.message}{#if form.createdId} <a class="link" href={`${data.basePath}/${form.createdId}`}>Open Job</a>{/if}</p>{/if}
 {#if !job||!selected}
  <header class="flex flex-wrap items-start justify-between gap-4"><div><p class="eyebrow">Sold work → Field execution</p><h1>Move the work forward</h1><p class="muted mt-2">Today’s assignments, next steps and what needs your attention.</p></div><a class="link" href={`${base}/estimates`}>Accepted estimates</a></header>
  <nav aria-label="Job views" class="flex flex-wrap gap-2">{#each [['today','Today'],['upcoming','Upcoming'],['attention','Needs attention'],['all','All jobs'],['schedule','Schedule']] as [key,label]}<button class:active={view===key} class="secondary" aria-pressed={view===key} disabled={!ready} onclick={()=>view=key}>{label}</button>{/each}</nav>
  <div class="divide-y divide-[var(--border)]">{#each rows as row}<a class="job-row block py-5" href={`${data.basePath}/${row.id}`}><div class="flex flex-wrap justify-between gap-2"><h2>{row.name}</h2><span class="eyebrow">{row.stateLabel||jobLabel(row.state)}</span></div><p class="muted mt-1">{row.customerName} · {row.jobSiteName||row.trade}</p><p class="mt-3">{row.nextAction}</p><div class="mt-2 flex flex-wrap gap-4 text-sm">{#if row.scheduledStart}<span>{new Date(row.scheduledStart).toLocaleString()}</span>{/if}{#if row.atRisk}<span>Planned completion has passed</span>{/if}{#if row.blockers}<span class="flex items-center gap-1"><AlertTriangle size={16}/>{row.blockers} readiness items</span>{/if}</div></a>{:else}<p class="muted py-10">No jobs in this view. Check All jobs or hand off an accepted estimate.</p>{/each}</div>
  {#if data.workspace.canWrite&&data.workspace.configuration.allowManual}<details class="panel"><summary>Create a service, warranty or imported Job</summary><p class="muted mb-3">Use accepted Estimates for sold work. Manual work records its origin.</p><form method="POST" action="?/save" use:enhance={submit} class="grid gap-4 sm:grid-cols-2"><input type="hidden" name="action" value="create"/><label>Job name<input name="name" required/></label><label>Origin<select name="origin">{#each ['Manual','Warranty','Service','Imported','Internal','Other'] as origin}<option>{origin}</option>{/each}</select></label><label>Customer<select name="customerId" required><option value="">Choose customer</option>{#each data.choices.customers as c}<option value={c.id}>{c.name}</option>{/each}</select></label><label>Site<select name="jobSiteId" required><option value="">Choose site</option>{#each data.choices.sites as s}<option value={s.id}>{s.name} · {s.address}</option>{/each}</select></label><label>Trade<select name="tradeProfile">{#each data.workspace.configuration.enabledTrades as trade}<option>{trade}</option>{/each}</select></label><label>Service / job type<input name="serviceType"/></label><label>Scope<textarea name="scope" required></textarea></label><div><label>Import source system<input name="sourceSystem"/></label><label>External ID<input name="externalId"/></label></div><button class="btn-primary" disabled={disabled}>Create Job</button></form></details>{/if}
  {#if data.workspace.canConfigure}<a class="link inline-block" href={`${data.basePath}/settings`}>Job rules & trade profiles</a>{/if}
 {:else}
  <a class="link inline-flex items-center gap-2" href={data.basePath}><ArrowLeft size={18}/>Jobs</a>
  <header><p class="eyebrow">{selected.stateLabel} · {execution?.tradeProfile||'Legacy job'}</p><h1 class="mt-2">{job.name}</h1><p class="muted mt-2">{job.customerName} · {job.jobSiteName}</p><p class="mt-2 flex items-center gap-2"><MapPin size={18}/>{job.projectAddress||'Site details not linked'}</p>{#if job.contactPhone}<a class="link inline-block" href={`tel:${job.contactPhone}`}>Call {job.customerName}</a>{/if}<div class="mt-3 flex flex-wrap gap-4"><button class="secondary" aria-pressed={fieldMode} onclick={()=>fieldMode=!fieldMode}>{fieldMode?'Field view · Show planning':'Planning view · Show field tasks'}</button>{#if job.leadId}<a class="link" href={`${base}/leads/${job.leadId}`}>Source Lead</a>{/if}{#if job.estimateId}<a class="link" href={`${base}/estimates/${job.estimateId}`}>Accepted estimate</a>{/if}</div></header>
  <section class="panel current"><p class="eyebrow">Current task</p><h2 class="mt-1">{selected.nextAction}</h2>{#if blockers.length}<ul class="my-3 list-disc space-y-1 pl-5">{#each blockers as blocker}<li>{blocker}</li>{/each}</ul>{:else if execution}<p class="mt-3 flex items-center gap-2"><CheckCircle2 size={18}/>Current readiness checks pass.</p>{/if}
   {#if selected.canWrite&&!execution}<p class="muted my-3">Apply trade execution requirements to this existing Job. Its original history remains available.</p>{@render command('adopt','Use execution workflow')}
   {:else if selected.canWrite&&execution}<form method="POST" action="?/save" use:enhance={submit} class="mt-4 flex flex-wrap items-end gap-3">{@render identity()}<input type="hidden" name="action" value="transition"/><label>Next step<select name="state">{#each selected.transitions as state}<option value={state}>{jobLabel(state)}</option>{/each}</select></label><label>Reason / handoff note<input name="text" required={['CLOSED','COMPLETED','CANCELLED'].includes(selected.state)}/></label><button class="btn-primary" disabled={disabled||selected.transitions.length===0}>Continue Job</button></form>{/if}
  </section>
  <section><h2>Approved scope</h2><p class="mt-3 whitespace-pre-wrap">{execution?.soldScope||job.description||'No scope recorded'}</p>{#if job.acceptedEstimate}<p class="muted mt-3">Accepted revision {job.acceptedEstimate.revision} · {job.acceptedEstimate.source}</p><p class="mt-2 whitespace-pre-wrap">{job.acceptedEstimate.document?.commitments}</p><details><summary>Customer commitments, terms & source files</summary><p>{job.acceptedEstimate.document?.terms}</p>{#each job.acceptedEstimate.document?.attachments??[] as file}<a class="link block" href={`${data.basePath}/${job.id}/files/${file.id}`}>{file.name}</a>{/each}{#each Object.entries(job.acceptedEstimate.document?.inputs??{}) as [key,input]}<p>{key}: {input.value} · {input.confirmed?"Confirmed":"Needs confirmation"}</p>{/each}{#each job.acceptedEstimate.selectedOptions??[] as option}<h3>{option.name}</h3>{#each option.lines as line}<p>{line.quantity} {line.unit} · {line.name}</p>{/each}{/each}</details>{/if}</section>
  {#if execution}
   <section class="space-y-3"><h2>Checklist</h2>{#each execution.tasks as task}<div class="task-row"><div><p class="font-medium">{task.title}</p><p class="muted text-sm">{task.completedAtUtc?'Completed':`${task.stage} requirement`}{task.evidenceRequired?' · Evidence required':''}</p></div>{#if !task.completedAtUtc&&selected.canWrite}<form method="POST" action="?/save" use:enhance={submit}>{@render identity()}<input type="hidden" name="action" value="task"/><input type="hidden" name="itemId" value={task.id}/>{#if task.evidenceRequired}<label>Evidence<select name="evidenceId" required><option value="">Choose uploaded evidence</option>{#each execution.evidence as e}<option value={e.id}>{e.name}</option>{/each}</select></label>{/if}<button class="secondary" disabled={disabled}>Complete<span class="sr-only"> {task.title}</span></button></form>{/if}</div>{/each}
   {#if selected.canWrite&&!fieldMode}<details><summary>Add task</summary><form method="POST" action="?/save" use:enhance={submit} class="space-y-3">{@render identity()}<input type="hidden" name="action" value="add-task"/><label>Task title<input name="title" required/></label><label>Required before<select name="stage"><option value="schedule">Scheduling</option><option value="start">Starting work</option><option value="complete">Completion</option></select></label><button class="secondary" disabled={disabled}>Add task</button></form></details>{/if}</section>
   {#if selected.canWrite}<section class="panel"><h2>Field activity</h2><form method="POST" action="?/save" use:enhance={submit} class="mt-3 space-y-3">{@render identity()}<input type="hidden" name="action" value="activity"/><label>Work performed, progress or observations<textarea name="text" rows="3" required placeholder="Use your device’s dictation key to capture a quick update."></textarea></label><button class="btn-primary" disabled={disabled}>Record update</button></form></section>{/if}
   <section><h2>Files & photos</h2><ul class="my-3">{#each execution.evidence as e}<li><a class="link inline-block" href={`${data.basePath}/${job.id}/files/${e.id}`}>{e.name}</a></li>{:else}<li class="muted">No execution evidence yet.</li>{/each}</ul>{#if selected.canWrite}<form method="POST" action="?/save" enctype="multipart/form-data" use:enhance={submit} class="space-y-3">{@render identity()}<input type="hidden" name="action" value="files"/><label>Evidence purpose<select name="purpose"><option value="field">Field progress</option><option value="completion">Completion evidence</option><option value="planning">Planning / release confirmation</option></select></label><label>Capture or upload evidence<input name="files" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" multiple required/></label><button class="secondary" disabled={disabled}>Upload evidence</button></form>{/if}</section>
   <details class="panel" open={execution.issues.some(i=>!i.resolvedAtUtc)}><summary>Issues & blockers ({execution.issues.filter(i=>!i.resolvedAtUtc).length} open)</summary>{#each execution.issues as issue}<div class="my-4"><h3>{issue.description}</h3><p class="muted">{issue.severity} · {issue.resolvedAtUtc?'Resolved':'Open'}</p>{#if !issue.resolvedAtUtc&&selected.canWrite}<form method="POST" action="?/save" use:enhance={submit} class="mt-2">{@render identity()}<input type="hidden" name="action" value="resolve-issue"/><input type="hidden" name="itemId" value={issue.id}/><label>Resolution<input name="text" required/></label><button class="secondary mt-2" disabled={disabled}>Resolve issue</button></form>{/if}</div>{/each}{#if selected.canWrite}<form method="POST" action="?/save" use:enhance={submit} class="space-y-3">{@render identity()}<input type="hidden" name="action" value="issue"/><label>Issue<textarea name="text" required></textarea></label><label>Type<select name="type">{#each ['site condition','customer','weather','material','equipment','permit','inspection','crew','safety','other'] as type}<option>{type}</option>{/each}</select></label><label>Severity<select name="severity"><option value="blocker">Blocks work</option><option value="critical">Critical</option><option value="warning">Warning</option><option value="info">Information</option></select></label><button class="secondary" disabled={disabled}>Report issue</button></form>{/if}</details>
   <details class="panel"><summary>Scope changes ({execution.changes.length})</summary>{#each execution.changes as change}<div class="my-4"><h3>{change.description}</h3><p class="muted">{jobLabel(change.status)}{change.pricingImpact?' · Pricing approval required':''}</p>{#if selected.canWrite&&!fieldMode}<form method="POST" action="?/save" use:enhance={submit} class="mt-3 space-y-2">{@render identity()}<input type="hidden" name="action" value="change-status"/><input type="hidden" name="itemId" value={change.id}/><label>Next change stage<select name="state">{#each ['REVIEW','PRICING_REQUIRED','APPROVAL_REQUIRED','APPROVED','DECLINED','IMPLEMENTED','CANCELLED'] as state}<option value={state}>{jobLabel(state)}</option>{/each}</select></label><label>Accepted change Estimate ID<input name="acceptedEstimateId"/></label><label>Customer approval / review note<input name="text"/></label><button class="secondary" disabled={disabled}>Update change</button></form>{/if}</div>{/each}{#if selected.canWrite}<form method="POST" action="?/save" use:enhance={submit} class="space-y-3">{@render identity()}<input type="hidden" name="action" value="change"/><label>Requested change<textarea name="text" required></textarea></label><label>Reason<input name="reason"/></label><label>Scope impact<input name="scopeImpact"/></label><label>Schedule impact<input name="scheduleImpact"/></label><label class="check"><input type="checkbox" name="pricingImpact"/>Requires pricing review</label><button class="secondary" disabled={disabled}>Capture change request</button></form>{/if}</details>
   <details class="panel" open={!fieldMode}><summary>Materials & equipment</summary>{#each execution.requirements as r}<p class="my-3">{r.quantity} {r.unit} · {r.description} · {r.status}</p>{#if selected.canWrite&&!fieldMode}<form method="POST" action="?/save" use:enhance={submit} class="flex flex-wrap items-end gap-2">{@render identity()}<input type="hidden" name="action" value="requirement"/><input type="hidden" name="itemId" value={r.id}/><input type="hidden" name="kind" value={r.kind}/><input type="hidden" name="description" value={r.description}/><input type="hidden" name="quantity" value={r.quantity}/><input type="hidden" name="unit" value={r.unit}/><label>Status<select name="status" value={r.status}>{#each ['Needed','Ordered','Confirmed','Available','Delivered','Consumed','Returned','Cancelled'] as s}<option>{s}</option>{/each}</select></label><button class="secondary" disabled={disabled}>Update requirement</button></form>{/if}{/each}{#if selected.canWrite&&!fieldMode}<form method="POST" action="?/save" use:enhance={submit} class="mt-4 grid gap-3 sm:grid-cols-2">{@render identity()}<input type="hidden" name="action" value="requirement"/><input type="hidden" name="status" value="Needed"/><label>Requirement<select name="kind"><option value="material">Material</option><option value="equipment">Equipment</option></select></label><label>Description<input name="description" required/></label><label>Quantity<input name="quantity" type="number" min="0.01" step="any" value="1" required/></label><label>Unit<input name="unit" value="each" required/></label><button class="secondary" disabled={disabled}>Add requirement</button></form>{/if}</details>
   <details class="panel" open={!fieldMode}><summary><CalendarDays size={18} class="inline"/> Schedule & assignments</summary>{#each selected.events as event}<p class="my-3">{event.title} · {new Date(event.startUtc).toLocaleString()} – {new Date(event.endUtc).toLocaleTimeString()} · {event.eventStatus}</p>{#if selected.canWrite&&!fieldMode}<details><summary>Change {event.title}</summary><form method="POST" action="?/save" use:enhance={submit} class="space-y-3">{@render identity()}<input type="hidden" name="action" value="schedule"/><input type="hidden" name="eventId" value={event.id}/><input type="hidden" name="title" value={event.title}/><input type="hidden" name="type" value={event.jobEventType}/><input type="hidden" name="resources" value={(event.resourceIds??[]).join(',')}/><input type="hidden" name="customerVisible" value={String(event.customerVisible)}/><input type="hidden" name="startUtc" value={event.startUtc}/><input type="hidden" name="endUtc" value={event.endUtc}/>{#each event.membershipIds as member}<input type="hidden" name="membershipId" value={member}/>{/each}<label>Revised start<input type="datetime-local" value={localDate(event.startUtc)} onchange={e=>updateUtc(e,'startUtc')} required/></label><label>Revised end<input type="datetime-local" value={localDate(event.endUtc)} onchange={e=>updateUtc(e,'endUtc')} required/></label><label>Event status<select name="status" value={event.eventStatus}><option value="scheduled">Scheduled</option><option value="completed">Work event finished</option><option value="cancelled">Cancelled</option></select></label><label>Reason<input name="text" required/></label><button class="secondary" disabled={disabled}>Update Calendar event</button></form></details>{/if}{:else}<p class="muted mb-3">No work events scheduled.</p>{/each}<a class="link inline-block" href={`${base}/calendar`}>Company calendar</a>{#if selected.canWrite&&!fieldMode}<form method="POST" action="?/save" use:enhance={submit} class="mt-3 grid gap-3 sm:grid-cols-2">{@render identity()}<input type="hidden" name="action" value="schedule"/><input type="hidden" name="startUtc" value={start?new Date(start).toISOString():''}/><input type="hidden" name="endUtc" value={end?new Date(end).toISOString():''}/><label>Event title<input name="title" required/></label><label>Event type<select name="type">{#each ['work','delivery','mobilization','installation','inspection','punch list','walkthrough'] as type}<option>{type}</option>{/each}</select></label><label>Start<input type="datetime-local" bind:value={start} required/></label><label>End<input type="datetime-local" bind:value={end} required/></label><label>Assigned people<select name="membershipId" multiple required>{#each data.choices.members as m}<option value={m.id}>{m.name}{m.team?` · ${m.team}`:""}</option>{/each}</select></label><label>Equipment / resource references<input name="resources" placeholder="Separate resource names with commas"/></label><button class="secondary" disabled={disabled}>Save Calendar event</button></form><form method="POST" action="?/save" use:enhance={submit} class="mt-3">{@render identity()}<input type="hidden" name="action" value="recommend"/><input type="hidden" name="startUtc" value={start?new Date(start).toISOString():''}/><input type="hidden" name="endUtc" value={end?new Date(end).toISOString():''}/><button class="secondary" disabled={disabled||!start||!end}>Recommend qualified people for this window</button></form>{#if form?.recommendations}<ul class="my-3 space-y-2">{#each form.recommendations as r}<li><strong>{data.choices.members.find(m=>m.id===r.membershipId)?.name||'Team member'}</strong> · {r.explanation}</li>{/each}</ul>{/if}{/if}</details>
   {#if selected.canWrite&&!fieldMode}<details class="panel"><summary>Job responsibility & site</summary><form method="POST" action="?/save" use:enhance={submit} class="space-y-3">{@render identity()}<input type="hidden" name="action" value="owner"/><label>Responsible person<select name="ownerMembershipId" value={execution.ownerMembershipId??''} required><option value="">Choose a person</option>{#each data.choices.members as m}<option value={m.id}>{m.name}</option>{/each}</select></label><button class="secondary" disabled={disabled}>Assign responsibility</button></form>{#if !job.jobSiteId}<form method="POST" action="?/save" use:enhance={submit} class="space-y-3 mt-4">{@render identity()}<input type="hidden" name="action" value="site"/><label>Link existing site<select name="itemId" required><option value="">Choose a site</option>{#each data.choices.sites as s}<option value={s.id}>{s.name} · {s.address}</option>{/each}</select></label><button class="secondary" disabled={disabled}>Link primary site</button></form>{/if}</details>{/if}
   {#if !fieldMode&&Object.keys(execution.profile.fields).length}<details class="panel"><summary>Trade execution details</summary><form method="POST" action="?/save" use:enhance={submit} class="space-y-3">{@render identity()}<input type="hidden" name="action" value="trade-data"/>{#each Object.entries(execution.profile.fields) as [key,label]}<label>{label}<textarea name={`field.${key}`} value={execution.tradeData[key]||''} readonly={!selected.canWrite}></textarea></label>{/each}{#if selected.canWrite}<button class="secondary" disabled={disabled}>Confirm details</button>{/if}</form></details>{/if}
   {#if ['READY_FOR_COMPLETION','COMPLETION_REVIEW','COMPLETED','CLOSED'].includes(selected.state)}<section class="panel"><h2>Completion & customer acceptance</h2>{#each execution.acceptances as a}<p class="my-3">{a.signer} · {new Date(a.acceptedAtUtc).toLocaleString()}<br/>{a.statement}{#if a.exceptions}<br/>Exceptions: {a.exceptions}{/if}</p>{:else}<p class="muted my-3">No customer completion acceptance recorded.</p>{/each}{#if selected.canWrite&&['COMPLETION_REVIEW','COMPLETED'].includes(selected.state)}<form method="POST" action="?/save" use:enhance={submit} class="space-y-3">{@render identity()}<input type="hidden" name="action" value="accept"/><label>Customer / signer<input name="signer" required/></label><label>Exact completion statement<textarea name="statement" required>I confirm the completed work described in this Job.</textarea></label><label>Outstanding exceptions<textarea name="exceptions"></textarea></label><label>Signature / confirmation<input name="signature" required/></label><p class="muted text-sm">Record the customer’s confirmation. This is separate from proposal acceptance.</p><button class="btn-primary" disabled={disabled}>Record customer acceptance</button></form>{/if}</section>{/if}
  {/if}
  <details class="panel"><summary><Sparkles size={18} class="inline"/> Bob operations coordinator</summary><p class="muted my-3">Readiness uses recorded requirements. Mutations follow your permissions and tenant action policy.</p><form method="POST" action="?/save" use:enhance={submit} class="my-4 space-y-3">{@render identity()}<input type="hidden" name="action" value="bob"/><input type="hidden" name="tool" value="job.structure"/><label>Dictated field note<textarea name="text" placeholder="Work: Installed frame. Issue: Opening differs from plan. Material: Need replacement hardware." required></textarea></label><button class="secondary" disabled={disabled}>Structure note for review</button></form>{#if structured?.observation}<p class="my-3">{structured.observation}</p>{#each structured.possibleIssues??[] as issue}<p>Possible issue: {issue}</p>{/each}{#each structured.possibleRequirements??[] as requirement}<p>Possible requirement: {requirement}</p>{/each}<p class="muted mt-3">{structured.nextAction}</p>{/if}{#if selected.canWrite&&!fieldMode}<form method="POST" action="?/save" use:enhance={submit} class="my-4 space-y-3">{@render identity()}<input type="hidden" name="action" value="bob"/><input type="hidden" name="tool" value="job.notify"/><label>Customer update<select name="template">{#each ['scheduled','arriving','rescheduled','information-needed','change-approval','completed','acceptance-request'] as t}<option>{t}</option>{/each}</select></label><label>Preferred channel<select name="channel"><option value="email">Email</option><option value="sms">SMS</option></select></label><button class="secondary" disabled={disabled}>Ask Bob to notify customer</button></form>{/if}<form method="POST" action="?/save" use:enhance={submit}>{@render identity()}<input type="hidden" name="action" value="bob"/><input type="hidden" name="tool" value="job.readiness"/><button class="secondary" disabled={disabled}>Ask Bob to review readiness</button></form>{#if form?.bob?.confirmationRequired}<form method="POST" action="?/save" use:enhance={submit} class="mt-3">{@render identity()}<input type="hidden" name="action" value="approve-bob"/><input type="hidden" name="actionId" value={form.bob.id}/><p>Tenant policy requires approval.</p><button class="btn-primary" disabled={disabled}>Approve Bob action</button></form>{/if}{#if form?.bob&&!form.bob.confirmationRequired}<ul class="my-3 list-disc pl-5">{#each blockers as b}<li>{b}</li>{:else}<li>No current readiness blockers.</li>{/each}</ul>{/if}</details>
  {#if data.notifications?.length}<details class="panel"><summary>Customer notification receipts</summary><ol class="space-y-4 py-3">{#each data.notifications as receipt}<li><p>{receipt.template} · {receipt.channel}</p><p>{receipt.message}</p><p class="muted text-xs">{new Date(receipt.createdAtUtc).toLocaleString()}</p></li>{/each}</ol></details>{/if}
  <details class="panel"><summary>Activity & audit history</summary><ol class="space-y-4 py-3">{#each job.activity as a}<li><p>{a.label}</p>{#if a.note}<p>{a.note}</p>{/if}<p class="muted text-xs">{new Date(a.occurredAtUtc).toLocaleString()} · {a.type}</p></li>{/each}</ol></details>
 {/if}
</section>
{#snippet identity()}<input type="hidden" name="id" value={job?.id}/><input type="hidden" name="version" value={job?.version}/>{/snippet}
{#snippet command(action:string,label:string)}<form method="POST" action="?/save" use:enhance={submit}>{@render identity()}<input type="hidden" name="action" value={action}/><button class="btn-primary" disabled={disabled}>{label}</button></form>{/snippet}
<style>
 .jobs{color:var(--text-strong)}h1{font-size:clamp(1.6rem,3vw,2.2rem);font-weight:650;line-height:1.2}h2{font-size:1.15rem;font-weight:650}.eyebrow{font-size:.78rem;font-weight:650;letter-spacing:.04em;text-transform:uppercase;color:var(--teal-text)}.muted{color:var(--text-muted)}.panel{padding:1.15rem;border:1px solid var(--border);border-radius:.6rem;background:var(--surface)}.current{border-left:4px solid var(--teal-text)}.notice{padding:1rem;border:1px solid var(--border);background:var(--surface)}.link{min-height:44px;align-content:center;text-decoration:underline;text-underline-offset:3px}label{display:block;font-size:.875rem;font-weight:600}input:not([type=checkbox]):not([type=hidden]),select,textarea{display:block;width:100%;margin-top:.4rem;padding:.65rem;min-height:44px;border:1px solid var(--border-strong);border-radius:.4rem;color:var(--text-strong);background:var(--surface);font-weight:400}.check{display:flex;align-items:center;gap:.6rem;min-height:44px}.secondary{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;min-height:44px;padding:.6rem .9rem;border:1px solid var(--border-strong);border-radius:.4rem;background:var(--surface)}.active{border-color:var(--teal-text);font-weight:700}.task-row{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:1rem;padding:.7rem 0;border-bottom:1px solid var(--border)}summary{min-height:44px;align-content:center;cursor:pointer;font-weight:600}.btn-primary{min-height:44px}:is(button,a,input,select,textarea,summary):focus-visible{outline:3px solid var(--teal-text);outline-offset:3px}button:disabled{opacity:.55}details,form{min-width:0}.job-row:hover{background:var(--surface)}
